128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
131	        List<String> missingFields = new ArrayList<>();
132	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
133	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
134	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
135	        requireNonBlank(missingFields, "address", normalizedAddress);
136	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
137	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
138	        if (!missingFields.isEmpty()) {
139	            throw new MissingRequiredFieldsException(missingFields);
140	        }
141	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
142	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
143	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
144	        requireDailyLimitNotReached(registrationDate);
145	        requireCityBelowCapacity(ownerFieldsDto.getCity());
146	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
147	        requireUniqueTelephone(normalizedTelephone);
148	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
149	        if (!sharesHousehold) {
150	            requireUniqueHousehold(ownerFieldsDto.getLastName(), normalizedAddress);
151	        }
152	        ownerFieldsDto.setTelephone(normalizedTelephone);
153	        if (ownerFieldsDto.getEmail() != null) {
154	            String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
155	            requireUniqueEmail(normalizedEmail);
156	            ownerFieldsDto.setEmail(normalizedEmail);
157	        }
158	        HttpHeaders headers = new HttpHeaders();
159	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
160	        owner.setAddress(normalizedAddress);
161	        owner.setRegistrationDate(registrationDate);
162	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
163	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
164	        if (sharesHousehold) {
165	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
166	        }
167	        this.clinicService.saveOwner(owner);
168	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
169	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
170	            ownerMapper.toMembershipLevel(owner));
171	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
