181	        if (currentOwner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        currentOwner.setAddress(ownerFieldsDto.getAddress());
185	        currentOwner.setCity(ownerFieldsDto.getCity());
186	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
187	        currentOwner.setLastName(ownerFieldsDto.getLastName());
188	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
189	        this.clinicService.saveOwner(currentOwner);
190	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
191	    }
