270	    /**
271	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
272	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
273	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
274	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
275	     *
276	     * @param city the owner's city (already validated non-blank)
277	     * @param lastName the owner's last name (already validated non-blank)
278	     * @return the formatted customer code for the owner being created
279	     */
280	    private String nextCustomerCode(String city, String lastName) {
281	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
282	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
283	        int sequence = (int) this.clinicService.findAllOwners().stream()
284	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
285	            .count() + 1;
286	        return String.format("%s-%s-%04d", city3, last3, sequence);
287	    }
288	
289	    /**
290	     * Counts the existing owners (those already persisted before this create) whose first and last
291	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
292	     * the new owner as its {@code namesakeCount} and echoed back on reads.
293	     *
294	     * @param firstName the incoming owner's first name (already validated non-blank)
295	     * @param lastName the incoming owner's last name (already validated non-blank)
296	     * @return the number of existing namesakes sharing both names case-insensitively
297	     */
298	    private int countNamesakes(String firstName, String lastName) {
299	        return (int) this.clinicService.findAllOwners().stream()
300	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
301	                && lastName.equalsIgnoreCase(existing.getLastName()))
302	            .count();
303	    }
304	
305	    /**
306	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
307	     * whitespace-only), so the caller can reject the request listing every offending field.
308	     */
309	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
310	        if (value == null || value.isBlank()) {
311	            missingFields.add(fieldName);
312	        }
313	    }
314	
315	    /**
316	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
317	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
318	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
319	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
320	     * {@code "+61412345678"}.
321	     *
322	     * @param telephone the raw telephone value from the request
323	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
324	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
325	     */
326	    private static String normalizeTelephone(String telephone) {
327	        String e164 = toE164(telephone);
328	        if (e164 == null) {
329	            throw new InvalidFieldValueException("telephone",
330	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
331	        }
332	        return e164;
333	    }
334	
335	    /**
336	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
337	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
338	     * owners' stored numbers when detecting duplicates.
339	     */
340	    private static String toE164(String telephone) {
341	        if (telephone == null) {
342	            return null;
343	        }
344	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
345	        String digits;
346	        if (cleaned.startsWith("+")) {
347	            digits = cleaned.substring(1);
348	        } else {
349	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
350	            digits = "61" + national;
351	        }
352	        if (!digits.matches("[0-9]{8,15}")) {
353	            return null;
354	        }
355	        if (!hasValidNationalLength(digits)) {
356	            return null;
357	        }
358	        return "+" + digits;
359	    }
360	
361	    /**
362	     * Checks the national-number length against the country code for the country codes that pin one.
363	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
364	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
365	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
366	     */
367	    private static boolean hasValidNationalLength(String digits) {
368	        if (digits.startsWith("61")) {
369	            return digits.length() - 2 == 9;
370	        }
371	        if (digits.startsWith("1")) {
372	            return digits.length() - 1 == 10;
373	        }
374	        return true;
375	    }
376	
377	    /**
378	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
379	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
380	     *
381	     * @param email the raw email value from the request (already known to be non-null)
382	     * @return the lower-cased email to be stored and returned
383	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
384	     */
385	    private static String normalizeEmail(String email) {
386	        String trimmed = email.trim();
387	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
388	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
389	        }
390	        return trimmed.toLowerCase(Locale.ROOT);
391	    }
392	
393	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
394	    private static final int MAX_OWNERS_PER_CITY = 50;
395	
396	    /**
397	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
398	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
399	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
400	     *
401	     * @param city the incoming owner's city (already validated non-blank)
402	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
403	     */
404	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
405	    private static final int MAX_OWNERS_PER_DAY = 100;
406	
407	    /**
408	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
409	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
410	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
411	     * date rolled forward to a business day), so this caps the number that may be created per day.
412	     *
413	     * @param businessDay the adjusted business-day registration date of the owner being created
414	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
415	     */
416	    /**
417	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
418	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
419	     */
420	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
421	
422	    /**
423	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
424	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
425	     * owner's registration date, otherwise {@code false}.
426	     *
427	     * @param owner the owner to map
428	     * @return the owner DTO with its bulk-signup warning flag populated
429	     */
430	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
431	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
432	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
433	        return ownerDto;
434	    }
435	
436	    /**
437	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
438	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
439	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
440	     */
441	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
442	        if (registrationDate == null) {
443	            return false;
444	        }
445	        long registeredThatDay = this.clinicService.findAllOwners().stream()
446	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
447	            .count();
448	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
449	    }
450	
451	    private void requireDailyLimitNotReached(LocalDate businessDay) {
452	        long registeredThatDay = this.clinicService.findAllOwners().stream()
453	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
454	            .count();
455	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
456	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
457	        }
458	    }
459	
460	    /**
461	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
462	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
463	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
464	     * is recorded on the next business day, and every value derived from the registration date uses the
465	     * adjusted date.
466	     *
467	     * @param date the effective registration date (supplied or defaulted), never {@code null}
468	     * @return the same date, or the next Monday when {@code date} is a weekend
469	     */
470	    private static LocalDate toBusinessDay(LocalDate date) {
471	        DayOfWeek day = date.getDayOfWeek();
472	        if (day == DayOfWeek.SATURDAY) {
473	            return date.plusDays(2);
474	        }
475	        if (day == DayOfWeek.SUNDAY) {
476	            return date.plusDays(1);
477	        }
478	        return date;
479	    }
480	
481	    private void requireCityBelowCapacity(String city) {
482	        long cityOwners = this.clinicService.findAllOwners().stream()
483	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
484	            .count();
485	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
486	            throw new CityAtCapacityException(city);
487	        }
488	    }
489	
490	    /**
491	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
492	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
493	     *
494	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
495	     * @throws DuplicateTelephoneException if another owner already uses this telephone
496	     */
497	    private void requireUniqueTelephone(String normalizedTelephone) {
498	        boolean taken = this.clinicService.findAllOwners().stream()
499	            .map(Owner::getTelephone)
500	            .map(OwnerRestControllerV1::toE164)
501	            .filter(existing -> existing != null)
502	            .anyMatch(normalizedTelephone::equals);
503	        if (taken) {
504	            throw new DuplicateTelephoneException(normalizedTelephone);
505	        }
506	    }
507	
508	    /**
509	     * Rejects the request when {@code normalizedEmail} is already used by any existing owner,
510	     * comparing on the lower-cased email so differently-cased stored addresses still collide.
511	     *
512	     * @param normalizedEmail the incoming owner's normalized (lower-cased) email
513	     * @throws DuplicateEmailException if another owner already uses this email
514	     */
515	    private void requireUniqueEmail(String normalizedEmail) {
516	        boolean taken = this.clinicService.findAllOwners().stream()
517	            .map(Owner::getEmail)
518	            .filter(existing -> existing != null)
519	            .map(existing -> existing.trim().toLowerCase(Locale.ROOT))
520	            .anyMatch(normalizedEmail::equals);
521	        if (taken) {
522	            throw new DuplicateEmailException(normalizedEmail);
523	        }
524	    }
525	
526	    /**
527	     * Rejects the request when another owner already shares this household, i.e. has both the same
528	     * last name and the same address once each value is normalized (trimmed, internal whitespace
529	     * runs collapsed to a single space, and compared case-insensitively). Callers skip this check
530	     * when the request opts in via {@code sharesHousehold}.
531	     *
532	     * @param lastName the incoming owner's last name (already validated non-blank)
533	     * @param address the incoming owner's address (already validated non-blank)
534	     * @throws DuplicateHouseholdException if another owner already has this last name and address
535	     */
536	    private void requireUniqueHousehold(String lastName, String address) {
537	        String normalizedLastName = normalizeForHousehold(lastName);
538	        String normalizedAddress = householdAddressKey(address);
539	        boolean taken = this.clinicService.findAllOwners().stream()
540	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
541	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress));
542	        if (taken) {
543	            throw new DuplicateHouseholdException(lastName, address);
544	        }
545	    }
546	
547	    /**
548	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
549	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
550	     * comparisons are case-insensitive.
551	     */
552	    private static String normalizeForHousehold(String value) {
553	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
554	    }
555	
556	    /**
557	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
558	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
559	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
560	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
561	     * value normalizes to the empty string, so the required-field check rejects an address that is
562	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
563	     *
564	     * @param address the raw address value from the request (may be {@code null})
565	     * @return the normalized address, or the empty string when blank after normalization
566	     */
567	    private static String normalizeAddress(String address) {
568	        if (address == null) {
569	            return "";
570	        }
571	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
572	        if (collapsed.isEmpty()) {
573	            return "";
574	        }
575	        String[] tokens = collapsed.split(" ");
576	        StringBuilder sb = new StringBuilder();
577	        for (String token : tokens) {
578	            String expanded = switch (token) {
579	                case "ST" -> "STREET";
580	                case "RD" -> "ROAD";
581	                case "AVE" -> "AVENUE";
582	                default -> token;
583	            };
584	            if (sb.length() > 0) {
585	                sb.append(' ');
586	            }
587	            sb.append(expanded);
588	        }
589	        return sb.toString();
590	    }
591	
592	    /**
593	     * Derives the comparison key for an address used by household-duplicate detection and the shared
594	     * household identifier: the address is first put in its canonical normalized form and then
595	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
596	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
597	     */
598	    private static String householdAddressKey(String address) {
599	        return normalizeForHousehold(normalizeAddress(address));
600	    }
601	
602	    /**
603	     * Joins the household identified by this last name and address, returning the stable shared
604	     * {@code householdId} to store on the joining owner. The identifier is derived deterministically
605	     * from the normalized last name and address, so every owner in the same household resolves to the
606	     * same value. Any existing household members that predate this feature (or were created without
607	     * opting in) are back-filled with the shared identifier so the whole household agrees.
608	     *
609	     * @param lastName the joining owner's last name (already validated non-blank)
610	     * @param address the joining owner's address (already validated non-blank)
611	     * @return the shared household identifier for this last name and address
612	     */
613	    private String joinHousehold(String lastName, String address) {
614	        String normalizedLastName = normalizeForHousehold(lastName);
615	        String normalizedAddress = householdAddressKey(address);
616	        String householdId = householdIdFor(normalizedLastName, normalizedAddress);
617	        this.clinicService.findAllOwners().stream()
618	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
619	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
620	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
621	            .forEach(existing -> {
622	                existing.setHouseholdId(householdId);
623	                this.clinicService.saveOwner(existing);
624	            });
625	        return householdId;
626	    }
627	
628	    /**
629	     * Derives a stable household identifier from the already-normalized last name and address as the
630	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
631	     * always maps to the same identifier.
632	     */
633	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
634	        try {
635	            byte[] digest = MessageDigest.getInstance("SHA-256")
636	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
637	            StringBuilder sb = new StringBuilder();
638	            for (byte b : digest) {
639	                sb.append(String.format("%02X", b));
640	            }
641	            return sb.substring(0, 12);
642	        }
643	        catch (NoSuchAlgorithmException e) {
644	            throw new IllegalStateException("SHA-256 not available", e);
645	        }
646	    }
647	}
