16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
23	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
24	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "toMembershipNumber")
25	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
26	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
27	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
32	     * email, otherwise {@code 'PHONE'}.
33	     */
34	    @Named("toContactPreference")
35	    default String toContactPreference(Owner owner) {
36	        if (owner == null) {
37	            return null;
38	        }
39	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
40	        return hasEmail ? "EMAIL" : "PHONE";
41	    }
42	
43	    /**
44	     * Fixed city-to-region table used to derive an owner's locality.
45	     */
46	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
47	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
48	
49	    /**
50	     * Derives the owner's locality as the canonical region for the owner's city from the fixed
51	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
52	     * or {@code 'UNKNOWN'} when the city is not in the table.
53	     */
54	    @Named("toLocality")
55	    default String toLocality(Owner owner) {
56	        if (owner == null) {
57	            return null;
58	        }
59	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
60	    }
61	
62	    /**
63	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
64	     */
65	    @Named("toDisplayName")
66	    default String toDisplayName(Owner owner) {
67	        if (owner == null) {
68	            return null;
69	        }
70	        return owner.getLastName() + ", " + owner.getFirstName();
71	    }
72	
73	    /**
74	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
75	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
76	     */
77	    @Named("toInitials")
78	    default String toInitials(Owner owner) {
79	        if (owner == null) {
80	            return null;
81	        }
82	        return initial(owner.getFirstName()) + initial(owner.getLastName());
83	    }
84	
85	    /**
86	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
87	     * the last two digits of the {@code registrationDate} year, e.g. {@code 'SYD-SMI-0007-M26'}. Returns
88	     * {@code null} when either the customer code or the registration date is absent.
89	     */
90	    @Named("toMembershipNumber")
91	    default String toMembershipNumber(Owner owner) {
92	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
93	            return null;
94	        }
95	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
96	    }
97	
98	    /**
99	     * Returns the owner's numeric membership level, assigned on creation: starts at {@code 1}, plus
100	     * {@code 1} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
101	     * ({@code namesakeCount} is 0), capped at {@code 3} (level 4 is reserved for tenure).
102	     */
103	    @Named("toMembershipLevel")
104	    default Integer toMembershipLevel(Owner owner) {
105	        if (owner == null) {
106	            return null;
107	        }
108	        int level = 1;
109	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
110	        if (hasEmail) {
111	            level++;
112	        }
113	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
114	        if (noNamesakes) {
115	            level++;
116	        }
117	        return Math.min(level, 3);
118	    }
119	
120	    private static String initial(String name) {
121	        if (name == null || name.isEmpty()) {
122	            return "";
123	        }
124	        return Character.toUpperCase(name.charAt(0)) + ".";
125	    }
126	
127	    Owner toOwner(OwnerDto ownerDto);
128	
129	    @Mapping(target = "id", ignore = true)
130	    @Mapping(target = "pets", ignore = true)
131	    Owner toOwner(OwnerFieldsDto ownerDto);
132	
133	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
134	
135	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
136	
