17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingErrorsResponse errors = new BindingErrorsResponse();
138	        BindingResult bindingResult = e.getBindingResult();
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
140	        if (bindingResult.hasErrors()) {
141	            errors.addAllErrors(bindingResult);
142	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
143	                .map(fieldError -> {
144	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
145	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
146	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
147	                        fieldError.getField(),
148	                        defaultMessage,
149	                        rejectedValue);
150	                    return new ValidationMessageDto(message)
151	                        .putAdditionalProperty("field", fieldError.getField())
152	                        .putAdditionalProperty("rejectedValue", rejectedValue)
153	                        .putAdditionalProperty("defaultMessage", defaultMessage);
154	                })
155	                .toList();
156	            logger.debug("Validation error at {} {}: {}",
157	                request.getMethod(),
158	                request.getRequestURI(),
159	                bindingResult.getFieldErrors());
160	            List<String> errorFields = bindingResult.getFieldErrors().stream()
161	                .map(FieldError::getField)
162	                .distinct()
163	                .toList();
164	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
165	            detail.setProperty("errors", errorFields);
166	            return ResponseEntity.status(status).body(detail);
167	        }
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Handles {@link MissingRequiredFieldsException} raised when a request omits or leaves blank one
173	     * or more required fields. Returns a 400 Bad Request whose body carries an {@code errors} array
174	     * listing the name of each offending field.
175	     *
176	     * @param e The {@link MissingRequiredFieldsException} to be handled
177	     * @param request {@link HttpServletRequest} object referring to the current request.
178	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
179	     */
180	    @ExceptionHandler(MissingRequiredFieldsException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleMissingRequiredFieldsException(MissingRequiredFieldsException e, HttpServletRequest request) {
183	        HttpStatus status = HttpStatus.BAD_REQUEST;
184	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
185	        detail.setProperty("errors", e.getFields());
186	        logger.debug("Missing required fields at {} {}: {}",
187	            request.getMethod(),
188	            request.getRequestURI(),
189	            e.getFields());
190	        return ResponseEntity.status(status).body(detail);
191	    }
192	
193	    /**
194	     * Handles {@link InvalidFieldValueException} raised when a request supplies a field whose value
195	     * is present but violates a business rule (for example a telephone number that is not exactly
196	     * ten digits after stripping non-digit characters). Returns a 400 Bad Request whose body carries
197	     * an {@code errors} array listing the name of each offending field.
198	     *
199	     * @param e The {@link InvalidFieldValueException} to be handled
200	     * @param request {@link HttpServletRequest} object referring to the current request.
201	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
202	     */
203	    @ExceptionHandler(InvalidFieldValueException.class)
204	    @ResponseBody
205	    public ResponseEntity<ProblemDetail> handleInvalidFieldValueException(InvalidFieldValueException e, HttpServletRequest request) {
206	        HttpStatus status = HttpStatus.BAD_REQUEST;
207	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
208	        detail.setProperty("errors", e.getFields());
209	        logger.debug("Invalid field value at {} {}: {}",
210	            request.getMethod(),
211	            request.getRequestURI(),
212	            e.getFields());
213	        return ResponseEntity.status(status).body(detail);
214	    }
215	
216	    /**
217	     * Handles {@link DuplicateTelephoneException} raised when a request attempts to create an owner
218	     * whose normalized telephone number is already used by another owner. Returns a 409 Conflict
219	     * whose body carries an {@code errors} array naming the offending field.
220	     *
221	     * @param e The {@link DuplicateTelephoneException} to be handled
222	     * @param request {@link HttpServletRequest} object referring to the current request.
223	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
224	     */
225	    @ExceptionHandler(DuplicateTelephoneException.class)
226	    @ResponseBody
227	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
228	        HttpStatus status = HttpStatus.CONFLICT;
229	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
230	        detail.setProperty("errors", e.getFields());
231	        logger.debug("Duplicate telephone at {} {}: {}",
232	            request.getMethod(),
233	            request.getRequestURI(),
234	            e.getFields());
235	        return ResponseEntity.status(status).body(detail);
236	    }
237	
238	    /**
239	     * Handles {@link DuplicateHouseholdException} raised when a request attempts to create an owner
240	     * whose last name and address already belong to another owner (compared case-insensitively with
241	     * collapsed whitespace) without opting in via {@code sharesHousehold}. Returns a 409 Conflict
242	     * whose body carries an {@code errors} array naming the offending fields.
243	     *
244	     * @param e The {@link DuplicateHouseholdException} to be handled
245	     * @param request {@link HttpServletRequest} object referring to the current request.
246	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
247	     */
248	    @ExceptionHandler(DuplicateHouseholdException.class)
249	    @ResponseBody
250	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
251	        HttpStatus status = HttpStatus.CONFLICT;
252	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
253	        detail.setProperty("errors", e.getFields());
254	        logger.debug("Duplicate household at {} {}: {}",
255	            request.getMethod(),
256	            request.getRequestURI(),
257	            e.getFields());
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	    /**
262	     * Handles {@link DuplicateEmailException} raised when a request attempts to create an owner
263	     * whose lower-cased email is already used by another owner. Returns a 409 Conflict whose body
264	     * carries an {@code errors} array naming the offending field.
265	     *
266	     * @param e The {@link DuplicateEmailException} to be handled
267	     * @param request {@link HttpServletRequest} object referring to the current request.
268	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
269	     */
270	    @ExceptionHandler(DuplicateEmailException.class)
271	    @ResponseBody
272	    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(DuplicateEmailException e, HttpServletRequest request) {
273	        HttpStatus status = HttpStatus.CONFLICT;
274	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
275	        detail.setProperty("errors", e.getFields());
276	        logger.debug("Duplicate email at {} {}: {}",
277	            request.getMethod(),
278	            request.getRequestURI(),
279	            e.getFields());
280	        return ResponseEntity.status(status).body(detail);
281	    }
282	
283	    /**
284	     * Handles {@link CityAtCapacityException} raised when a request attempts to create an owner
285	     * whose city already contains the maximum number of owners (50 or more). Returns a 409 Conflict
286	     * whose body carries an {@code errors} array naming the offending field.
287	     *
288	     * @param e The {@link CityAtCapacityException} to be handled
289	     * @param request {@link HttpServletRequest} object referring to the current request.
290	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
291	     */
292	    @ExceptionHandler(CityAtCapacityException.class)
293	    @ResponseBody
294	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
295	        HttpStatus status = HttpStatus.CONFLICT;
296	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
297	        detail.setProperty("errors", e.getFields());
298	        logger.debug("City at capacity at {} {}: {}",
299	            request.getMethod(),
300	            request.getRequestURI(),
301	            e.getFields());
302	        return ResponseEntity.status(status).body(detail);
303	    }
304	
305	    /**
306	     * Handles {@link DailyOwnerLimitException} raised when a request attempts to create an owner
307	     * once the maximum number of owners for the current day (100 or more, by {@code registrationDate})
308	     * has already been reached. Returns a 429 Too Many Requests.
309	     *
310	     * @param e The {@link DailyOwnerLimitException} to be handled
311	     * @param request {@link HttpServletRequest} object referring to the current request.
312	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
313	     */
314	    @ExceptionHandler(DailyOwnerLimitException.class)
315	    @ResponseBody
316	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
317	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
318	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
319	        logger.debug("Daily owner limit reached at {} {}",
320	            request.getMethod(),
321	            request.getRequestURI());
322	        return ResponseEntity.status(status).body(detail);
323	    }
324	
325	}
